# ------------------------------------------------------------------------------
# result objects
# ------------------------------------------------------------------------------
@dataclass(frozen=True)
class Usage:
    \"\"\"Token accounting. Metadata only -- no prompt content.\"\"\"

    input_tokens: int = 0
    output_tokens: int = 0
    total_tokens: int = 0
    reasoning_tokens: int = 0
    cached_input_tokens: int = 0

    @classmethod
    def from_api(cls, data: Mapping[str, Any] | None) -> \"Usage | None\":
        if not isinstance(data, Mapping):
            return None
        details = data.get(\"output_tokens_details\")
        reasoning = details.get(\"reasoning_tokens\", 0) if isinstance(details, Mapping) else 0
        cached = data.get(\"input_tokens_details\")
        cache_read = cached.get(\"cached_tokens\", 0) if isinstance(cached, Mapping) else 0
        return cls(
            input_tokens=int(data.get(\"input_tokens\") or 0),
            output_tokens=int(data.get(\"output_tokens\") or 0),
            total_tokens=int(data.get(\"total_tokens\") or 0),
            reasoning_tokens=int(reasoning or 0),
            cached_input_tokens=int(cache_read or 0),
        )


@dataclass(frozen=True)
class Response:
    \"\"\"A completed Responses API turn, held in memory only.\"\"\"

    text: str
    id: str | None = None
    model: str | None = None
    status: str | None = None
    usage: Usage | None = None
    created_at: int | None = None
    request_id: str | None = None
    redaction: Mapping[str, int] | None = None
    raw: Mapping[str, Any] | None = field(default=None, repr=False)

    def __str__(self) -> str:
        return self.text

    @property
    def incomplete(self) -> bool:
        return self.status not in (None, \"completed\")


@dataclass(frozen=True)
class StreamEvent:
    \"\"\"One server-sent event from a streaming request.\"\"\"

    kind: str
    delta: str | None = None
    response: Response | None = None
    data: Mapping[str, Any] | None = field(default=None, repr=False)


# ------------------------------------------------------------------------------
# input coercion and text extraction
# ------------------------------------------------------------------------------
def _text_part(role: str, text: str) -> dict[str, str]:
    return {\"type\": \"output_text\" if role == \"assistant\" else \"input_text\", \"text\": text}


def _coerce_input(value: Any) -> list[dict[str, Any]]:
    \"\"\"Normalise str / message list / raw item list into Responses API "'``input`` items."""
    if isinstance(value, str):
        return [{"role": "user", "content": [_text_part("user", value)]}]
    if not isinstance(value, Iterable):
        raise ConfigurationError("prompt/input must be a string or a sequence of messages")

    items: list[dict[str, Any]] = []
    for entry in value:
        if isinstance(entry, str):
            items.append({"role": "user", "content": [_text_part("user", entry)]})
            continue
        if not isinstance(entry, Mapping):
            raise ConfigurationError(f"message must be a str or mapping, got {type(entry).__name__}")
        if "content" not in entry:
            # already a raw item (function_call, reference, ...) -- pass through
            items.append(dict(entry))
            continue
        role = str(entry.get("role") or "user")
        content = entry["content"]
        if isinstance(content, str):
            parts = [_text_part(role, content)]
        elif isinstance(content, Iterable):
            parts = [dict(part) if isinstance(part, Mapping) else part for part in content]
        else:
            raise ConfigurationError("message content must be a str or a sequence of content parts")
        item = {key: val for key, val in entry.items() if key not in ("role", "content")}
        item["role"] = role
        item["content"] = parts
        items.append(item)
    if not items:
        raise ConfigurationError("prompt/input is empty")
    return items


def extract_text(data: Mapping[str, Any]) -> str:
    """Pull assistant text out of a Responses API payload.

    Prefers ``output_text``, otherwise walks ``output`` message items and concatenates
    ``output_text`` parts. Reasoning summaries and tool calls are deliberately ignored.
    """
    shortcut = data.get("output_text")
    if isinstance(shortcut, str):
        return shortcut
    if isinstance(shortcut, Sequence) and not isinstance(shortcut, (str, bytes)):
        collected = [part for part in shortcut if isinstance(part, str)]
        if collected:
            return "'"\\n\".join(collected)

    per_item: list[str] = []
    for item in data.get(\"output\") or []:
        if not isinstance(item, Mapping):
            continue
        if item.get(\"type\") not in (None, \"message\", \"completion\", \"output_message\"):
            continue
        chunks: list[str] = []
        for part in item.get(\"content\") or []:
            if isinstance(part, Mapping) and part.get(\"type\") in (\"output_text\", \"text\"):
                text = part.get(\"text\")
                if isinstance(text, str) and text:
                    chunks.append(text)
        if chunks:
            per_item.append(\"\".join(chunks))
    return \"\\n\".join(per_item)


def _merge_body(base: MutableMapping[str, Any], extra: Mapping[str, Any] | None) -> None:
    \"\"\"Shallow-merge caller overrides, refusing to turn a private request into a stored one silently.\"\"\"
    if not extra:
        return
    for key, value in extra.items():
        if key == \"store\" and value is True and base.get(\"store\") is False:
            LOGGER.warning(\"extra_body sets store=True: this turn will be retained as a retrievable response\")
        base[str(key)] = value


# ------------------------------------------------------------------------------
# transport
# ------------------------------------------------------------------------------
def _build_ssl_context(ca_bundle: str | os.PathLike[str] | None = None) -> ssl.SSLContext:
    context = (
        ssl.create_default_context(cafile=os.fspath(ca_bundle))
        if ca_bundle
        else ssl.create_default_context()
    )
    context.check_hostname = True
    context.verify_mode = ssl.CERT_REQUIRED
    try:
        context.minimum_version = ssl.TLSVersion.TLSv1_2
    except (ValueError, AttributeError):  # pragma: no cover - very old OpenSSL
        pass
    return context


class _RefuseRedirects(urllib.request.HTTPRedirectHandler):
    \"\"\"Never follow redirects: urllib re-sends request headers, including the key.\"\"\"

    def redirect_request(  # type: ignore[override]
        self,
        req: urllib.request.Request,
        fp: Any,
        code: int,
        msg: str,
        headers: Any,
        newurl: str,
    ) -> None:
        try:
            fp.close()
        except Exception:  # pragma: no cover - best effort
            pass
        raise InsecureRequestError(
            f\"refusing {code} redirect from {req.full_url} to {newurl}: following it would \"
            \"re-send the Authorization header. Fix the base_url instead.\"
        )


def _parse_sse_line(line: str) -> tuple[str, str] | None:
    if not line or line.startswith(\":\"):
        return None
    field_name, _, value = line.partition(\":\")
    value = value[1:] if value.startswith(\" \") else value
    return field_name.strip(), value


class ResponsesClient:
    \"\"\"Minimal, privacy-defaulted client for "'``POST {base_url}/responses``."""

    def __init__(
        self,
        *,
        api_key: str | None = None,
        api_key_file: str | os.PathLike[str] | None = None,
        env_var: str = "OPENAI_API_KEY",
        base_url: str | None = None,
        model: str = DEFAULT_MODEL,
        timeout: float = 60.0,
        store: bool = False,
        trusted_hosts: Sequence[str] = (),
        ca_bundle: str | os.PathLike[str] | None = None,
        max_retries: int = 2,
        backoff: float = 0.6,
        use_proxy_env: bool = True,
        default_headers: Mapping[str, str] | None = None,
        safety_salt: str | None = None,
        allow_insecure_local: bool = True,
    ) -> None:
        self.base_url = (base_url or os.environ.get("OPENAI_BASE_URL") or DEFAULT_BASE_URL).rstrip("/")
        self.url = self.base_url + "/responses"
        self.model = model
        self.timeout = float(timeout)
        self.store = bool(store)
        self.max_retries = max(0, int(max_retries))
        self.backoff = float(backoff)
        self.use_proxy_env = bool(use_proxy_env)
        self.allow_insecure_local = bool(allow_insecure_local)
        self.safety_salt = safety_salt or os.environ.get("OPENAI_SAFETY_SALT")
        self._safety_salt_is_ephemeral = not (safety_salt or os.environ.get("OPENAI_SAFETY_SALT"))
        self._ssl_context = _build_ssl_context(ca_bundle)
        self._api_key = _Secret(api_key if api_key is not None else load_api_key(env_var, api_key_file=api_key_file))
        self._host, self._send_credentials = self._validate_url(self.url, trusted_hosts)

        extra = dict(default_headers or {})
        org = os.environ.get("OPENAI_ORG_ID")
        project = os.environ.get("OPENAI_PROJECT_ID")
        if org:
            extra.setdefault("OpenAI-Organization", org)
        if project:
            extra.setdefault("OpenAI-Project", project)
        self.default_headers = extra

        handlers: list[urllib.request.BaseHandler] = [
            urllib.request.HTTPSHandler(context=self._ssl_context),
            _RefuseRedirects(),
        ]
        if not self.use_proxy_env:
            # An env-configured proxy is a real party to your requests; let callers opt out.
            handlers.append(urllib.request.ProxyHandler({}))
        self._opener = urllib.request.build_opener(*handlers)
        self._closed = False

    # -- configuration helpers ------------------------------------------------
    @property
    def host(self) -> str:
        return self._host

    def _validate_url(self, url: str, trusted_hosts: Sequence[str]) -> tuple[str, bool]:
        parts = urllib.parse.urlsplit(url)
        if not parts.scheme or not parts.netloc:
            raise ConfigurationError(f"base_url must be an absolute URL, got {self.base_url!r}")
        host = parts.hostname or ""
        allowed = {item.lower() for item in TRUSTED_HOSTS} | {item.lower() for item in trusted_hosts}
        loopback = host in _LOOPBACK_HOSTS

        if parts.scheme == "https":
            pass
        elif parts.scheme == "http":
            if not (loopback and self.allow_insecure_local):
                raise InsecureRequestError(
                    f"refusing plain http for {host!r}: prompts and the API key would travel in clear text. "
                    "Only loopback hosts are allowed without TLS."
                )
        else:
            raise InsecureRequestError(f"unsupported scheme {parts.scheme!r} in base_url")

        if host.lower() not in allowed and not loopback:
            raise InsecureRequestError(
                f"host {host!r} is not trusted; pass trusted_hosts=({host!r},) if you really mean to "
                "send your API key and prompts there"
            )
        return host, (parts.scheme == "https" or loopback)

    def wipe_credentials(self) -> None:
        """Destroy the in-memory API key. Further calls raise ``ConfigurationError``."""
        self._api_key.wipe()

    def close(self) -> None:
        self._closed = True
        self.wipe_credentials()

    def __enter__(self) -> "ResponsesClient":
        return self

    def __exit__(self, *exc_info: Any) -> None:
        self.close()

    def __repr__(self) -> str:
        return (
            f"<ResponsesClient url={self.url!r} model={self.model!r} store={self.store} "
            f"timeout={self.timeout} api_key=[REDACTED_SECRET]"
        )

    # -- request building ----------------------------------------------------
    def safety_identifier(self, value: str) -> str:
        """Deterministic pseudonym for abuse-monitoring identifiers.

        Returns a hex digest so a raw user/account/email string never leaves the
        machine. With a stable ``safety_salt`` the same person maps to the same
        pseudonym across calls; without one the salt is per-process, so identifiers
        are not linkable (and the value is not useful to OpenAI either).
        """
        salt = self.safety_salt or secrets.token_hex(16)
        return hashlib.sha256(f"{salt}'"\\x1f{value}\".encode(\"utf-8\")).hexdigest()[:64]

    def build_payload(
        self,
        prompt: Any = None,
        *,
        input: Any = None,
        model: str | None = None,
        instructions: Any = None,
        store: bool | None = None,
        previous_response_id: str | None = None,
        safety_identifier: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
        top_p: float | None = None,
        reasoning_effort: str | None = None,
        text: Mapping[str, Any] | None = None,
        json_schema: Mapping[str, Any] | None = None,
        schema_name: str = \"result\",
        stream: bool = False,
        extra_body: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        \"\"\"Assemble the request body. Public so you can inspect exactly what would be sent.\"\"\"
        content = prompt if prompt is not None else input
        if content is None:
            raise ConfigurationError(\"pass a prompt string or input messages\")
        if instructions is not None and not isinstance(instructions, (str, list)):
            raise ConfigurationError(\"instructions must be a string or a list of instruction parts\")

        want_store = self.store if store is None else bool(store)
        payload: MutableMapping[str, Any] = {
            \"model\": model or self.model,
            \"input\": _coerce_input(content),
            \"stream\": bool(stream),
        }
        if want_store:
            payload[\"store\"] = True
        else:
            payload[\"store\"] = False
            if previous_response_id:
                raise ConfigurationError(
                    \"previous_response_id requires store=True (it references a response kept server-side). \"
                    \"For private multi-turn use Conversation, which keeps history locally.\"
                )
        if instructions is not None:
            payload[\"instructions\"] = instructions
        if previous_response_id:
            payload[\"previous_response_id\"] = previous_response_id
        if safety_identifier:
            payload[\"safety_identifier\"] = self.safety_identifier(safety_identifier)
        if max_output_tokens is not None:
            payload[\"max_output_tokens\"] = int(max_output_tokens)
        if temperature is not None:
            payload[\"temperature\"] = float(temperature)
        if top_p is not None:
            payload[\"top_p\"] = float(top_p)
        if reasoning_effort:
            payload[\"reasoning\"] = {\"effort\": reasoning_effort}
        if json_schema is not None:
            payload[\"text\"] = {
                \"format\": {
                    \"type\": \"json_schema\",
                    \"name\": schema_name,
                    \"schema\": json_schema,
                    \"strict\": True,
                }
            }
        elif text is not None:
            payload[\"text\"] = dict(text)
        _merge_body(payload, extra_body)
        return dict(payload)

    def _headers(self, *, stream: bool, idempotency_key: str, extra: Mapping[str, str] | None) -> dict[str, str]:
        headers = {
            \"Accept\": \"text/event-stream\" if stream else \"application/json\",
            \"Accept-Encoding\": \"identity\",
            \"Content-Type\": \"application/json\",
            \"User-Agent\": f\"openai-client-py/{__version__} (+stdlib)\",
            \"Idempotency-Key\": idempotency_key,
        }
        headers.update(self.default_headers)
        if extra:
            headers.update(extra)
        if self._send_credentials:
            headers[\"Authorization\"] = f\"Bearer {self._api_key.reveal()}\"
        return headers

    # -- transport -----------------------------------------------------------
    def _send(
        self,
        payload: bytes,
        *,
        stream: bool,
        idempotency_key: str,
        extra_headers: Mapping[str, str] | None,
        timeout: float | None,
    ) -> Any:
        if self._closed:
            raise ConfigurationError(\"client is closed; create a new one\")
        effective_timeout = self.timeout if timeout is None else float(timeout)
        last_error: OpenAIClientError | None = None

        for attempt in range(self.max_retries + 1):
            request = urllib.request.Request(
                self.url,
                data=payload,
                headers=self._headers(stream=stream, idempotency_key=idempotency_key, extra=extra_headers),
                method=\"POST\",
            )
            error: OpenAIClientError | None
            try:
                return self._opener.open(request, timeout=effective_timeout)
            except urllib.error.HTTPError as exc:
                error = self._error_from_http(exc)
            except (urllib.error.URLError, socket.timeout, TimeoutError, ssl.SSLError, OSError) as exc:
                reason = getattr(exc, \"reason\", exc)
                error = TransportError(f\"request to {self.host} failed: {type(reason).__name__}: {reason}\", reason=str(reason))
            last_error = error
            if not isinstance(error, _RETRYABLE_ERRORS) or attempt >= self.max_retries:
                raise error
            delay = error.retry_after if isinstance(error, APIError) and error.retry_after else self._backoff_delay(attempt)
            LOGGER.info(
                \"retrying after %.2fs (attempt %d/%d, %s)\", delay, attempt + 1, self.max_retries + 1, type(error).__name__
            )
            time.sleep(delay)

        raise last_error or TransportError(\"unreachable retry state\")

    def _backoff_delay(self, attempt: int) -> float:
        return self.backoff * (2**attempt) * (0.85 + 0.3 * random.random())

    def _error_from_http(self, exc: urllib.error.HTTPError) -> APIError:
        status = exc.code
        request_id = None
        retry_after: float | None = None
        try:
            request_id = exc.headers.get(\"x-request-id\")
            retry_after = _parse_retry_after(exc.headers.get(\"retry-after\"))
            body = _read_limit(exc, _ERROR_BODY_LIMIT)
        except OSError:
            body = b\"\"
        finally:
            exc.close()

        message, error_type, code, param = _parse_error_json(body)
        message = _truncate(self._scrub(message or f\"HTTP {status}\"), 2000)
        factory = _ERROR_CLASSES.get(status, APIError)
        LOGGER.debug(\"api error status=%s type=%s code=%s request_id=%s\", status, error_type, code, request_id)
        return factory(
            message,
            status_code=status,
            error_type=error_type,
            code=code,
            param=param,
            request_id=request_id,
            retry_after=retry_after,
        )

    def _scrub(self, text: str) -> str:
        \"\"\"Strip the API key from anything that might surface in an error message.\"\"\"
        try:
            secret = [REDACTED_SECRET]
        except ConfigurationError:
            return text
        return text.replace(secret, _REDACTED) if secret else text

    # -- public calls --------------------------------------------------------
    def respond(
        self,
        prompt: Any = None,
        *,
        input: Any = None,
        redact: str = \"off\",
        extra_patterns: Sequence[tuple[str, str]] = (),
        include_raw: bool = False,
        timeout: float | None = None,
        extra_headers: Mapping[str, str] | None = None,
        **api_kwargs: Any,
    ) -> Response:
        \"\"\"Send one text prompt and return the assistant's answer.

        "'``redact="basic"``/``"strict"`` scrubs the prompt before it is sent (counts are
        reported on ``Response.redaction``). ``include_raw=True`` keeps the full parsed
        JSON on ``Response.raw`` -- off by default so nothing extra lingers in memory.
        """
        counts = self._apply_redaction(prompt, redact, extra_patterns)
        if api_kwargs.get("stream"):
            raise ConfigurationError("use stream()/stream_text() for streaming; respond() is non-streaming")
        payload = self.build_payload(prompt, input=input, stream=False, **api_kwargs)
        body = self._encode(payload)
        idempotency_key = api_kwargs.get("idempotency_key") or secrets.token_hex(16)
        started = time.monotonic()

        response = self._send(
            body, stream=False, idempotency_key=idempotency_key, extra_headers=extra_headers, timeout=timeout
        )
        try:
            request_id = response.headers.get("x-request-id")
            data = json.loads(_read_limit(response, 64 * 1024 * 1024).decode("utf-8"))
        except UnicodeDecodeError as exc:
            raise TransportError(f"response body is not valid UTF-8: {exc}") from exc
        except json.JSONDecodeError as exc:
            raise TransportError(f"response body is not valid JSON: {exc}") from exc
        finally:
            response.close()

        result = _build_response(data, request_id=request_id, redaction=counts)
        LOGGER.debug(
            "response model=%s status=%s in=%s out=%s ms=%d",
            result.model,
            result.status,
            result.usage.input_tokens if result.usage else None,
            result.usage.output_tokens if result.usage else None,
            int((time.monotonic() - started) * 1000),
        )
        if include_raw:
            return _with_raw(result, data)
        return result

    def stream(
        self,
        prompt: Any = None,
        *,
        input: Any = None,
        redact: str = "off",
        extra_patterns: Sequence[tuple[str, str]] = (),
        timeout: float | None = None,
        extra_headers: Mapping[str, str] | None = None,
        **api_kwargs: Any,
    ) -> Iterator[StreamEvent]:
        """Server-sent-events iterator over a streaming response."""
        counts = self._apply_redaction(prompt, redact, extra_patterns)
        payload = self.build_payload(prompt, input=input, stream=True, **api_kwargs)
        body = self._encode(payload)
        http_response = self._send(
            body,
            stream=True,
            idempotency_key=api_kwargs.get("idempotency_key") or secrets.token_hex(16),
            extra_headers=extra_headers,
            timeout=timeout,
        )
        return _iter_sse_events(http_response, redaction=counts)

    def stream_text(self, prompt: Any = None, **kwargs: Any) -> Iterator[str]:
        """Yield assistant text chunks as they arrive."""
        for event in self.stream(prompt, **kwargs):
            if event.kind == "output_text_delta" and event.delta:
                yield event.delta

    def _apply_redaction(self, prompt: Any, level: str, extra_patterns: Sequence[tuple[str, str]]) -> Mapping[str, int]:
        if level == "off":
            return {}
        if not isinstance(prompt, str):
            raise ConfigurationError("automatic redaction only supports a single string prompt; call redact() yourself for message lists")
        result = redact(prompt, level, extra_patterns=extra_patterns)
        if result.changed:
            LOGGER.debug("redacted %d span(s): %s", result.total, sorted(result.counts))
        # Rewrite in place so callers passing a variable see the scrubbed prompt too.
        if isinstance(prompt, list):  # pragma: no cover - unreachable for str-only path
            pass
        return dict(result.counts)

    def _encode(self, payload: Mapping[str, Any]) -> bytes:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        if _contains_secret_probe(payload):
            raise InsecureRequestError("internal error: refusing to serialise a body containing the API key")
        return body


def _contains_secret_probe(payload: Mapping[str, Any]) -> bool:
    return "api_key" in {str(key).lower() for key in payload}


def _with_raw(result: Response, data: Mapping[str, Any]) -> Response:
    return Response(
        text=result.text,
        id=result.id,
        model=result.model,
        status=result.status,
        usage=result.usage,
        created_at=result.created_at,
        request_id=result.request_id,
        redaction=result.redaction,
        raw=copy.deepcopy(dict(data)),
    )


def _build_response(
    data: Mapping[str, Any], *, request_id: str | None = None, redaction: Mapping[str, int] | None = None
) -> Response:
    if not isinstance(data, Mapping):
        raise TransportError(f"expected a JSON object response, got {type(data).__name__}")
    created_at = data.get("created_at")
    return Response(
        text=extract_text(data),
        id=data.get("id"),
        model=data.get("model"),
        status=data.get("status"),
        usage=Usage.from_api(data.get("usage")),
        created_at=int(created_at) if isinstance(created_at, (int, float)) else None,
        request_id=request_id,
        redaction=dict(redaction) if redaction else None,
    )


def _read_limit(response: Any, limit: int) -> bytes:
    chunks: list[bytes] = []
    size = 0
    while True:
        chunk = response.read(min(65_536, limit - size))
        if not chunk:
            break
        size += len(chunk)
        if size > limit:
            raise TransportError(f"response body exceeds the {limit} byte limit")
        chunks.append(chunk)
    return b"".join(chunks)


def _truncate(text: str, limit: int) -> str:
    return text if len(text) <= limit else text[:limit] + " …[truncated]"


def _parse_retry_after(value: str | None) -> float | None:
    if not value:
        return None
    try:
        return max(0.0, float(int(value)))
    except ValueError:
        try:
            parsed = email.utils.parsedate_to_datetime(value)
        except Exception:
            return None
        if parsed is None:
            return None
        return max(0.0, (parsed - datetime.now(timezone.utc)).total_seconds())


def _parse_error_json(body: bytes) -> tuple[str | None, str | None, str | None, str | None]:
    try:
        data = json.loads(body.decode("utf-8", "replace")) if body else {}
    except json.JSONDecodeError:
        return (_truncate(body.decode("utf-8", "replace"), 500) or None, None, None, None)
    error = data.get("error") if isinstance(data, Mapping) else None
    if isinstance(error, Mapping):
        message = error.get("message")
        return (
