def _text_part(role: str, text: str) -> dict[str, str]:
    return {\"type\": \"output_text\" if role == \"assistant\" else \"input_text\", \"text\": text}


def _coerce_input(value: Any) -> list[dict[str, Any]]:
    \"\"\"Normalise str / message list / raw item list into Responses API "'``input`` items."""
    if isinstance(value, str):
        return [{"role": "user", "content": [_text_part("user", value)]}]
    if not isinstance(value, Iterable):
        raise ConfigurationError("prompt/input must be a string or a sequence of messages")

    items: list[dict[str, Any]] = []
    for entry in value:
        if isinstance(entry, str):
            items.append({"role": "user", "content": [_text_part("user", entry)]})
            continue
        if not isinstance(entry, Mapping):
            raise ConfigurationError(f"message must be a str or mapping, got {type(entry).__name__}")
        if "content" not in entry:
            # already a raw item (function_call, reference, ...) -- pass through
            items.append(dict(entry))
            continue
        role = str(entry.get("role") or "user")
        content = entry["content"]
        if isinstance(content, str):
            parts = [_text_part(role, content)]
        elif isinstance(content, Iterable):
            parts = [dict(part) if isinstance(part, Mapping) else part for part in content]
        else:
            raise ConfigurationError("message content must be a str or a sequence of content parts")
        item = {key: val for key, val in entry.items() if key not in ("role", "content")}
        item["role"] = role
        item["content"] = parts
        items.append(item)
    if not items:
        raise ConfigurationError("prompt/input is empty")
    return items


def extract_text(data: Mapping[str, Any]) -> str:
    """Pull assistant text out of a Responses API payload.

    Prefers ``output_text``, otherwise walks ``output`` message items and concatenates
    ``output_text`` parts. Reasoning summaries and tool calls are deliberately ignored.
    """
    shortcut = data.get("output_text")
    if isinstance(shortcut, str):
        return shortcut
    if isinstance(shortcut, Sequence) and not isinstance(shortcut, (str, bytes)):
        collected = [part for part in shortcut if isinstance(part, str)]
        if collected:
            return "'"\\n\".join(collected)

    per_item: list[str] = []
    for item in data.get(\"output\") or []:
        if not isinstance(item, Mapping):
            continue
        if item.get(\"type\") not in (None, \"message\", \"completion\", \"output_message\"):
            continue
        chunks: list[str] = []
        for part in item.get(\"content\") or []:
            if isinstance(part, Mapping) and part.get(\"type\") in (\"output_text\", \"text\"):
                text = part.get(\"text\")
                if isinstance(text, str) and text:
                    chunks.append(text)
        if chunks:
            per_item.append(\"\".join(chunks))
    return \"\\n\".join(per_item)


def _merge_body(base: MutableMapping[str, Any], extra: Mapping[str, Any] | None) -> None:
    \"\"\"Shallow-merge caller overrides, refusing to turn a private request into a stored one silently.\"\"\"
    if not extra:
        return
    for key, value in extra.items():
        if key == \"store\" and value is True and base.get(\"store\") is False:
            LOGGER.warning(\"extra_body sets store=True: this turn will be retained as a retrievable response\")
        base[str(key)] = value


