    def redirect_request(  # type: ignore[override]
        self,
        req: urllib.request.Request,
        fp: Any,
        code: int,
        msg: str,
        headers: Any,
        newurl: str,
    ) -> None:
        try:
            fp.close()
        except Exception:  # pragma: no cover - best effort
            pass
        raise InsecureRequestError(
            f\"refusing {code} redirect from {req.full_url} to {newurl}: following it would \"
            \"re-send the Authorization header. Fix the base_url instead.\"
        )


def _parse_sse_line(line: str) -> tuple[str, str] | None:
    if not line or line.startswith(\":\"):
        return None
    field_name, _, value = line.partition(\":\")
    value = value[1:] if value.startswith(\" \") else value
    return field_name.strip(), value


