        result = redact(prompt, level, extra_patterns=extra_patterns)
        if result.changed:
            LOGGER.debug("redacted %d span(s): %s", result.total, sorted(result.counts))
        # Rewrite in place so callers passing a variable see the scrubbed prompt too.
        if isinstance(prompt, list):  # pragma: no cover - unreachable for str-only path
            pass
        return dict(result.counts)

    def _encode(self, payload: Mapping[str, Any]) -> bytes:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        if _contains_secret_probe(payload):
            raise InsecureRequestError("internal error: refusing to serialise a body containing the API key")
        return body


def _contains_secret_probe(payload: Mapping[str, Any]) -> bool:
    return "api_key" in {str(key).lower() for key in payload}


def _with_raw(result: Response, data: Mapping[str, Any]) -> Response:
    return Response(
        text=result.text,
        id=result.id,
        model=result.model,
        status=result.status,
        usage=result.usage,
        created_at=result.created_at,
        request_id=result.request_id,
        redaction=result.redaction,
        raw=copy.deepcopy(dict(data)),
    )


def _build_response(
    data: Mapping[str, Any], *, request_id: str | None = None, redaction: Mapping[str, int] | None = None
) -> Response:
    if not isinstance(data, Mapping):
        raise TransportError(f"expected a JSON object response, got {type(data).__name__}")
    created_at = data.get("created_at")
    return Response(
        text=extract_text(data),
        id=data.get("id"),
        model=data.get("model"),
        status=data.get("status"),
        usage=Usage.from_api(data.get("usage")),
        created_at=int(created_at) if isinstance(created_at, (int, float)) else None,
        request_id=request_id,
        redaction=dict(redaction) if redaction else None,
    )


def _read_limit(response: Any, limit: int) -> bytes:
    chunks: list[bytes] = []
    size = 0
    while True:
        chunk = response.read(min(65_536, limit - size))
        if not chunk:
            break
        size += len(chunk)
        if size > limit:
            raise TransportError(f"response body exceeds the {limit} byte limit")
        chunks.append(chunk)
    return b"".join(chunks)


def _truncate(text: str, limit: int) -> str:
    return text if len(text) <= limit else text[:limit] + " …[truncated]"


def _parse_retry_after(value: str | None) -> float | None:
    if not value:
        return None
    try:
        return max(0.0, float(int(value)))
    except ValueError:
        try:
            parsed = email.utils.parsedate_to_datetime(value)
        except Exception:
            return None
        if parsed is None:
            return None
        return max(0.0, (parsed - datetime.now(timezone.utc)).total_seconds())


def _parse_error_json(body: bytes) -> tuple[str | None, str | None, str | None, str | None]:
    try:
        data = json.loads(body.decode("utf-8", "replace")) if body else {}
    except json.JSONDecodeError:
        return (_truncate(body.decode("utf-8", "replace"), 500) or None, None, None, None)
    error = data.get("error") if isinstance(data, Mapping) else None
    if isinstance(error, Mapping):
        message = error.get("message")
        return (
            str(message) if message else (json.dumps(dict(error))[:500] or None),
            error.get("type"),
            error.get("code"),
            error.get("param"),
        )
    if isinstance(error, str):
        return error, None, None, None
    if isinstance(data, Mapping) and data:
        return (json.dumps(dict(data))[:500], None, None, None)
    return (None, None, None, None)


_ERROR_CLASSES: Mapping[int, type[APIError]] = {
    401: AuthenticationError,
    403: AuthenticationError,
    429: RateLimitError,
}
for _status in range(500, 600):
    _ERROR_CLASSES[_status] = ServerError


def _iter_sse_events(http_response: Any, *, redaction: Mapping[str, int] | None = None) -> Iterator[StreamEvent]:
    fields: dict[str, str] = {}
    try:
        for raw_line in http_response:
            line = raw_line.decode("utf-8", "replace").rstrip("'"\\r\\n\")
            parsed = _parse_sse_line(line)
            if parsed is None:
                if not fields:
                    continue
                yield from _dispatch_event(fields.pop(\"event\", \"message\"), fields.pop(\"data\", \"\"), redaction)
                fields.clear()
                continue
            name, value = parsed
            if name == \"data\":
                fields[\"data\"] = fields.get(\"data\", \"\") + value
            else:
                fields[name] = value
    finally:
        try:
            http_response.close()
        except Exception:  # pragma: no cover - best effort
            pass


def _dispatch_event(kind: str, data: str, redaction: Mapping[str, int] | None) -> Iterator[StreamEvent]:
    if not data:
        return
    try:
        payload = json.loads(data)
    except json.JSONDecodeError:
        yield StreamEvent(kind=\"unparsable\", data={\"raw\": _truncate(data, 200)})
        return

    event_type = str(payload.get(\"type\") or kind)
    if event_type == \"response.output_text.delta\":
        yield StreamEvent(kind=\"output_text_delta\", delta=str(payload.get(\"text\") or payload.get(\"delta\") or \"\"))
        return
    if event_type in {\"response.created\", \"response.inprogress\", \"response.output_item.added\",
                      \"response.content_part.added\", \"response.refusal.delta\"}:
        delta = payload.get(\"delta\") if event_type == \"response.refusal.delta\" else None
        yield StreamEvent(kind=event_type.replace(\"response.\", \"\"), delta=str(delta) if delta else None, data=payload)
        return
    if event_type in {\"response.completed\", \"response.incomplete\", \"response.failed\"}:
        inner = payload.get(\"response\")
        inner = inner if isinstance(inner, Mapping) else payload
        response = _build_response(inner, redaction=redaction)
        yield StreamEvent(kind=event_type.replace(\"response.\", \"\"), response=response, data=payload)
        return
    if event_type == \"error\":
        error = payload.get(\"error\") if isinstance(payload.get(\"error\"), Mapping) else {}
        raise APIError(
            str(error.get(\"message\") or data),
            error_type=error.get(\"type\"),
            code=error.get(\"code\"),
            param=error.get(\"param\"),
        )
    yield StreamEvent(kind=event_type.replace(\"response.\", \"\"), data=payload)
